/* OneBox 1.0 — dependency-free PWA application layer. */
const $ = (selector, root = document) => root.querySelector(selector);
const tools = [['calculator', '⌗', '计算器'], ['calendar', '□', '日历'], ['weather', '◒', '天气'], ['convert', '⇄', '转换'], ['words', 'Aa', '单词']];
const STORAGE = { theme: 'onebox.theme', words: 'onebox.words', events: 'onebox.events', weather: 'onebox.weather', calculator: 'onebox.calculator', holidays: 'onebox.holidays' };
const today = new Date();
const nav = $('#toolNav');
const workspace = $('#workspace');
const uid = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
const pad = (value) => String(value).padStart(2, '0');
const dateKey = (date) => { const d = new Date(date); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; };
const dateFromKey = (key) => new Date(`${key}T12:00:00`);
const escapeHtml = (value = '') => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const parseStored = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
