const holidayStore = { ...(window.ONEBOX_HOLIDAY_DATA || {}) };
const holidayLoaded = new Set(Object.keys(holidayStore).map(String));
const holidaySource = 'https://raw.githubusercontent.com/NateScarlet/holiday-cn/master';
async function ensureHolidayYear(year) {
  if (holidayLoaded.has(String(year))) return;
  holidayLoaded.add(String(year));
  const cached = parseStored(`${STORAGE.holidays}.${year}`, null);
  if (cached) holidayStore[year] = cached;
  try {
    const response = await fetch(`${holidaySource}/${year}.json`, { headers: { Accept: 'application/json' } });
    if (!response.ok) throw new Error();
    const data = await response.json();
    holidayStore[year] = Object.fromEntries((data.days || []).map((item) => [item.date, { name: item.name, isOffDay: Boolean(item.isOffDay) }]));
    saveStored(`${STORAGE.holidays}.${year}`, holidayStore[year]);
    if (state.tool === 'calendar' && state.month.getFullYear() === Number(year)) render();
  } catch { /* the calendar remains useful with the bundled/current cache */ }
}
const holidayFor = (key) => holidayStore[key.slice(0, 4)]?.[key];

// Chinese lunar date and solar-term layer. Intl's calendar implementation is
// local and offline; the solar-term formula is the standard 21st-century
// Purple Mountain Observatory approximation (accurate to within a day).
const lunarMonthNumbers = { '正月': 1, '一月': 1, '二月': 2, '三月': 3, '四月': 4, '五月': 5, '六月': 6, '七月': 7, '八月': 8, '九月': 9, '十月': 10, '十一月': 11, '十二月': 12 };
const lunarDayNames = ['','初一','初二','初三','初四','初五','初六','初七','初八','初九','初十','十一','十二','十三','十四','十五','十六','十七','十八','十九','二十','廿一','廿二','廿三','廿四','廿五','廿六','廿七','廿八','廿九','三十'];
const lunarFormatter = (() => { try { return new Intl.DateTimeFormat('zh-CN-u-ca-chinese', { year: 'numeric', month: 'long', day: 'numeric' }); } catch { return null; } })();
function lunarFor(date) {
  if (!lunarFormatter) return null;
  const parts = Object.fromEntries(lunarFormatter.formatToParts(date).filter((item) => item.type !== 'literal').map((item) => [item.type, item.value]));
  const monthText = parts.month || '';
  const month = lunarMonthNumbers[monthText.replace('闰', '')] || 0;
  const day = Number(parts.day) || 0;
  const festivals = { '1-1': '春节', '1-15': '元宵节', '5-5': '端午节', '7-7': '七夕', '7-15': '中元节', '8-15': '中秋节', '9-9': '重阳节', '12-8': '腊八节', '12-23': '小年', '12-24': '小年' };
  const festival = festivals[`${month}-${day}`] || (month === 12 && day >= 29 ? '除夕' : '');
  return { month, day, monthText, dayText: lunarDayNames[day] || `${day}`, yearName: parts.yearName || '', festival, text: `${monthText}${lunarDayNames[day] || day}` };
}
const solarTermNames = ['小寒','大寒','立春','雨水','惊蛰','春分','清明','谷雨','立夏','小满','芒种','夏至','小暑','大暑','立秋','处暑','白露','秋分','寒露','霜降','立冬','小雪','大雪','冬至'];
const solarTermConstants21 = [5.4055, 20.12, 3.87, 18.73, 5.63, 20.646, 4.81, 20.1, 5.52, 21.04, 5.678, 21.37, 7.108, 22.83, 7.5, 23.13, 7.646, 23.042, 8.318, 23.438, 7.438, 22.36, 7.18, 21.94];
function solarTermsForYear(year) {
  const result = {};
  if (year < 1900 || year > 2099) return result;
  const y = year % 100;
  solarTermNames.forEach((name, index) => {
    const day = Math.floor(y * 0.2422 + solarTermConstants21[index]) - Math.floor((index < 4 ? y - 1 : y) / 4);
    const month = Math.floor(index / 2) + 1;
    result[`${year}-${pad(month)}-${pad(day)}`] = name;
  });
  return result;
}
const solarTermCache = {};
const solarTermFor = (key) => { const year = Number(key.slice(0, 4)); solarTermCache[year] ||= solarTermsForYear(year); return solarTermCache[year][key] || ''; };
const zodiacFor = (yearName) => ({ 子: '鼠', 丑: '牛', 寅: '虎', 卯: '兔', 辰: '龙', 巳: '蛇', 午: '马', 未: '羊', 申: '猴', 酉: '鸡', 戌: '狗', 亥: '猪' }[yearName?.slice(-1)] || '');
function calendarMeta(key) { const lunar = lunarFor(dateFromKey(key)); const holiday = holidayFor(key); const term = solarTermFor(key); return { lunar, holiday, term, label: term || lunar?.festival || holiday?.name || lunar?.dayText || '' }; }

// Shared heading and navigation ----------------------------------------------
function heading(title, subtitle, actions = '') { return `<div class="tool-head"><div><p class="section-kicker">ONEBOX TOOL</p><h2>${title}</h2><p>${subtitle}</p></div><div class="tool-actions">${actions}</div></div>`; }
function renderNav() { nav.innerHTML = tools.map(([id, icon, name]) => `<button class="tab ${state.tool === id ? 'active' : ''}" data-tool="${id}" aria-current="${state.tool === id ? 'page' : 'false'}"><span aria-hidden="true">${icon}</span>${name}</button>`).join(''); }
function selectTool(id) { if (!tools.some(([tool]) => tool === id)) id = 'calculator'; state.tool = id; if (location.hash.slice(1) !== id) history.replaceState(null, '', `#${id}`); renderNav(); render(); }

// Calculator -----------------------------------------------------------------
function tokenizeExpression(input) {
  const normalized = input.replace(/[xX]/g, '×').replace(/\s+/g, ''); const tokens = []; let index = 0;
  while (index < normalized.length) { const char = normalized[index]; if (/[0-9.]/.test(char)) { const start = index; let dots = 0; while (index < normalized.length && /[0-9.]/.test(normalized[index])) { if (normalized[index] === '.') dots++; index++; } const raw = normalized.slice(start, index); if (dots > 1 || raw === '.') throw Error('数字格式不正确'); tokens.push({ type: 'number', value: Number(raw) }); } else if ('+-−×÷*/()%'.includes(char)) { tokens.push({ type: 'operator', value: char === '*' ? '×' : char === '/' ? '÷' : char }); index++; } else throw Error('包含无法识别的字符'); }
  return tokens;
}
function evaluateExpression(input) {
  const tokens = tokenizeExpression(input); if (!tokens.length) return 0; let position = 0; const peek = () => tokens[position]; const take = () => tokens[position++]; const match = (value) => { if (peek()?.value === value) { position++; return true; } return false; };
  function primary() { if (match('(')) { const value = expression(); if (!match(')')) throw Error('括号不匹配'); return value; } const token = take(); if (!token || token.type !== 'number') throw Error('表达式不完整'); return token.value; }
  function unary() { if (match('+')) return unary(); if (match('−') || match('-')) return -unary(); let value = primary(); while (match('%')) value /= 100; return value; }
  function term() { let value = unary(); while (peek() && ['×', '÷'].includes(peek().value)) { const operator = take().value; const right = unary(); if (operator === '÷' && right === 0) throw Error('不能除以零'); value = operator === '×' ? value * right : value / right; } return value; }
  function expression() { let value = term(); while (peek() && ['+', '−', '-'].includes(peek().value)) { const operator = take().value; const right = term(); value = operator === '+' ? value + right : value - right; } return value; }
  const result = expression(); if (position !== tokens.length || !Number.isFinite(result)) throw Error('表达式无法计算'); return Number(result.toPrecision(12));
}
const calcKeys = ['AC', '⌫', '(', ')', '7', '8', '9', '÷', '4', '5', '6', '×', '1', '2', '3', '−', '0', '.', '%', '+', '±', '00', '='];
function calcPreview() { if (!state.calcExpr) return '0'; try { return formatNumber(evaluateExpression(state.calcExpr)); } catch { return '—'; } }
function saveCalculator() { saveStored(STORAGE.calculator, { expr: state.calcExpr, history: state.calcHistory.slice(0, 20) }); }
function calculator() { const history = state.calcHistory.length ? state.calcHistory.slice(0, 5).map((item) => `<button class="history-item" data-history="${escapeHtml(item.result)}"><span>${escapeHtml(item.expression)}</span><b>${escapeHtml(item.result)}</b></button>`).join('') : '<p class="empty compact">完成的计算会显示在这里。</p>'; return heading('计算器', '支持括号、百分比、键盘输入，并自动保留最近计算记录。', '<span class="saved-badge">● 本机保存</span>') + `<div class="calculator-layout"><div><div class="display" aria-live="polite"><div class="expression">${escapeHtml(state.calcExpr) || '准备计算'}</div><div class="result">${calcPreview()}</div></div><div class="keys">${calcKeys.map((key) => `<button class="key ${/[÷×−+%]/.test(key) ? 'op' : ''} ${key === '=' ? 'equal' : ''} ${key === 'AC' ? 'danger' : ''}" data-key="${key}" aria-label="${key === '⌫' ? '删除' : key}">${key}</button>`).join('')}</div><p class="keyboard-hint">键盘：数字、+ − × ÷、括号、Enter 等号、Esc 清空</p></div><aside class="history-panel"><div class="subhead"><h3>最近计算</h3><button class="text-btn" data-clear-calc-history ${state.calcHistory.length ? '' : 'disabled'}>清除</button></div>${history}</aside></div>`; }
function calculatorKey(key) { if (key === 'AC') { state.calcExpr = ''; state.calcJustEvaluated = false; } else if (key === '⌫') { state.calcExpr = state.calcExpr.slice(0, -1); state.calcJustEvaluated = false; } else if (key === '=') { try { const result = evaluateExpression(state.calcExpr); if (state.calcExpr) state.calcHistory.unshift({ expression: state.calcExpr, result: formatNumber(result), at: Date.now() }); state.calcExpr = String(result); state.calcJustEvaluated = true; } catch (error) { toast(error.message || '表达式无法计算', 'error'); } } else if (key === '±') { state.calcExpr = state.calcExpr.startsWith('-') ? state.calcExpr.slice(1) : `-${state.calcExpr || '0'}`; state.calcJustEvaluated = false; } else { if (state.calcJustEvaluated && (/[0-9.]/.test(key) || key === '(')) state.calcExpr = ''; state.calcJustEvaluated = false; state.calcExpr += key; } saveCalculator(); render(); }

// Calendar -------------------------------------------------------------------
function calendar() {
  const year = state.month.getFullYear(); const month = state.month.getMonth(); const first = new Date(year, month, 1); const start = (first.getDay() + 6) % 7; const days = new Date(year, month + 1, 0).getDate(); const previousDays = new Date(year, month, 0).getDate(); let cells = '';
  for (let index = 0; index < 42; index++) { let number; let date; let muted = false; if (index < start) { number = previousDays - start + index + 1; muted = true; date = new Date(year, month - 1, number); } else if (index >= start + days) { number = index - start - days + 1; muted = true; date = new Date(year, month + 1, number); } else { number = index - start + 1; date = new Date(year, month, number); } const key = dateKey(date); const meta = calendarMeta(key); const eventCount = state.events[key]?.length || 0; const holidayClass = meta.holiday ? (meta.holiday.isOffDay ? 'holiday' : 'workday') : ''; cells += `<button class="day ${muted ? 'muted' : ''} ${key === dateKey(today) ? 'today' : ''} ${key === state.selectedDate ? 'selected' : ''} ${holidayClass}" data-date="${key}" aria-label="${formatDate(key)}${meta.label ? `，${meta.label}` : ''}${eventCount ? `，${eventCount} 个日程` : ''}"><span>${number}</span><small>${escapeHtml(meta.term || meta.holiday?.name || meta.lunar?.festival || meta.lunar?.dayText || '')}</small>${eventCount ? `<i>${eventCount}</i>` : ''}</button>`; }
  const selected = calendarMeta(state.selectedDate); const selectedEvents = state.events[state.selectedDate] || []; const eventList = selectedEvents.length ? selectedEvents.map((item) => `<div class="event-item"><div><strong>${escapeHtml(item.title)}</strong><small>${item.time ? `${escapeHtml(item.time)} · ` : ''}${escapeHtml(item.note || '无备注')}</small></div><button class="icon-btn small" data-delete-event="${escapeHtml(item.id)}" aria-label="删除 ${escapeHtml(item.title)}">×</button></div>`).join('') : '<p class="empty compact">这一天还没有安排。</p>';
  const lunarLine = selected.lunar ? `${selected.lunar.yearName ? `${selected.lunar.yearName}年 · ` : ''}${selected.lunar.monthText}${selected.lunar.dayText}${selected.lunar.festival ? ` · ${selected.lunar.festival}` : ''}` : '当前浏览器不支持农历格式'; const status = selected.holiday ? `<span class="date-status ${selected.holiday.isOffDay ? 'off' : 'work'}">${selected.holiday.isOffDay ? '休' : '班'} · ${escapeHtml(selected.holiday.name)}</span>` : '<span class="date-status normal">工作日历</span>';
  return heading('日历', '公历、农历、节气、节假日、补班和个人日程集中查看。', '<button class="secondary" data-today>回到今天</button>') + `<div class="calendar-layout"><div class="calendar-card"><div class="calendar-top"><button class="icon-btn" data-month="-1" aria-label="上个月">←</button><strong>${year} 年 ${month + 1} 月</strong><button class="icon-btn" data-month="1" aria-label="下个月">→</button></div><div class="calendar-legend"><span><i class="dot off"></i>法定休息</span><span><i class="dot work"></i>补班</span><span><i class="dot term"></i>节气</span></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map((day) => `<div class="dow">周${day}</div>`).join('')}${cells}</div></div><aside class="agenda-panel"><div class="subhead"><div><p class="section-kicker">SELECTED DAY</p><h3>${formatDate(state.selectedDate)}</h3></div>${status}</div><div class="date-detail"><strong>${escapeHtml(lunarLine)}</strong>${selected.term ? `<span class="term-badge">${selected.term}</span>` : ''}<small>${selected.lunar?.yearName ? `农历${zodiacFor(selected.lunar.yearName)}年` : ''}</small></div><div class="event-list">${eventList}</div><form id="eventForm" class="event-form"><input type="hidden" id="eventDate" value="${state.selectedDate}"><div class="field"><label for="eventTitle">新增日程</label><input id="eventTitle" required maxlength="60" placeholder="例如：项目复盘"></div><div class="inline-fields"><input id="eventTime" type="time" aria-label="时间"><input id="eventNote" maxlength="120" placeholder="备注（可选）" aria-label="备注"></div><button class="primary" type="submit">添加到这一天</button></form></aside></div>`;
}
function saveEvents() { saveStored(STORAGE.events, state.events); }

// Weather --------------------------------------------------------------------
const weatherCode = (code) => { if (code === 0) return ['☀️', '晴']; if ([1,2,3].includes(code)) return ['⛅', '多云']; if ([45,48].includes(code)) return ['🌫️', '雾']; if ([51,53,55,56,57].includes(code)) return ['🌦️', '毛毛雨']; if ([61,63,65,66,67].includes(code)) return ['🌧️', '降雨']; if ([71,73,75,77].includes(code)) return ['🌨️', '降雪']; if ([80,81,82].includes(code)) return ['🌦️', '阵雨']; return ['⛈️', '雷雨']; };
const weatherUrl = (lat, lon) => `https://api.open-meteo.com/v1/forecast?latitude=${encodeURIComponent(lat)}&longitude=${encodeURIComponent(lon)}&current=temperature_2m,apparent_temperature,weather_code,relative_humidity_2m,wind_speed_10m,precipitation&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto&forecast_days=5`;
async function fetchWeather(lat, lon, name) { const request = ++state.weatherRequest; state.weatherLoading = true; state.weatherError = ''; render(); try { const response = await fetch(weatherUrl(lat, lon), { headers: { Accept: 'application/json' } }); if (!response.ok) throw Error('天气服务暂时不可用'); const data = await response.json(); if (request !== state.weatherRequest) return; state.weather = { ...data, name, latitude: lat, longitude: lon, updatedAt: Date.now() }; saveStored(STORAGE.weather, state.weather); } catch (error) { state.weatherError = error.message || '获取天气失败'; if (!state.weather) state.weather = parseStored(STORAGE.weather, null); } finally { if (request === state.weatherRequest) { state.weatherLoading = false; render(); } } }
async function searchWeather(city) { const query = city.trim(); if (!query) return toast('请输入城市名称', 'error'); state.weatherLoading = true; state.weatherError = ''; render(); try { const response = await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(query)}&count=1&language=zh&format=json`); const data = await response.json(); const place = data.results?.[0]; if (!place) throw Error('没有找到这个城市，请换个关键词'); await fetchWeather(place.latitude, place.longitude, [place.name, place.admin1, place.country].filter(Boolean).join(' · ')); } catch (error) { state.weatherLoading = false; state.weatherError = error.message || '城市搜索失败'; render(); } }
function weather() { const w = state.weather; const search = `<form id="weatherSearch" class="weather-search"><label class="sr-only" for="cityInput">搜索城市</label><input id="cityInput" placeholder="搜索城市，例如：苏州、Tokyo" autocomplete="off"><button class="primary" type="submit">搜索天气</button><button class="secondary" type="button" data-locate>当前位置</button></form>`; if (!w) return heading('天气', '搜索城市，查看实时天气与未来五日趋势。') + search + `<div class="empty weather-empty">${state.weatherLoading ? '<span class="loader"></span>正在获取天气…' : '天气需要联网，搜索一个城市开始。'}${state.weatherError ? `<strong class="error-text">${escapeHtml(state.weatherError)}</strong>` : ''}</div>`; const current = w.current || {}; const currentWeather = weatherCode(current.weather_code); const days = (w.daily?.time || []).map((day, index) => { const item = weatherCode(w.daily.weather_code[index]); return `<div class="forecast"><small>${new Intl.DateTimeFormat('zh-CN', { weekday: 'short' }).format(dateFromKey(day))}</small><b>${item[0]}</b><span>${Math.round(w.daily.temperature_2m_max[index])}° / ${Math.round(w.daily.temperature_2m_min[index])}°</span><small>${w.daily.precipitation_probability_max?.[index] ?? 0}% 降水</small></div>`; }).join(''); const updated = w.updatedAt ? `更新于 ${new Intl.DateTimeFormat('zh-CN', { hour: '2-digit', minute: '2-digit' }).format(w.updatedAt)}` : '来自本机缓存'; return heading('天气', `${escapeHtml(w.name || '当前位置')} · ${updated}`, '<button class="secondary" data-refresh-weather>刷新</button>') + search + `${state.weatherError ? `<div class="inline-alert">${escapeHtml(state.weatherError)}，当前显示上次成功结果。</div>` : ''}<div class="weather-now"><div><span class="weather-location">${escapeHtml(w.name || '当前位置')}</span><h3>${currentWeather[1]}</h3><strong>${Math.round(current.temperature_2m)}°</strong><p>体感 ${Math.round(current.apparent_temperature ?? current.temperature_2m)}° · 湿度 ${current.relative_humidity_2m ?? '—'}% · 风速 ${Math.round(current.wind_speed_10m ?? 0)} km/h</p></div><div class="weather-icon" aria-hidden="true">${currentWeather[0]}</div></div><div class="weather-days">${days}</div><p class="note">天气数据来自 Open-Meteo；最近一次成功结果会保存在本机，离线时仍可查看。</p>`; }

// Converter ------------------------------------------------------------------
const units = { length: { name: '长度', units: [['米','m',1],['千米','km',1000],['厘米','cm',.01],['毫米','mm',.001],['英寸','in',.0254],['英尺','ft',.3048],['英里','mi',1609.344]] }, weight: { name: '重量', units: [['克','g',1],['千克','kg',1000],['斤','斤',500],['磅','lb',453.59237],['盎司','oz',28.349523125]] }, area: { name: '面积', units: [['平方米','m²',1],['平方千米','km²',1e6],['公顷','ha',1e4],['亩','亩',2000/3],['平方英尺','ft²',.09290304]] }, volume: { name: '体积', units: [['升','L',1],['毫升','mL',.001],['立方米','m³',1000],['美制加仑','gal',3.785411784]] }, speed: { name: '速度', units: [['米/秒','m/s',1],['千米/时','km/h',1/3.6],['英里/时','mph',.44704],['节','kn',.514444]] }, time: { name: '时间', units: [['秒','s',1],['分钟','min',60],['小时','h',3600],['天','d',86400],['周','wk',604800]] }, data: { name: '数据', units: [['字节','B',1],['千字节','KB',1024],['兆字节','MB',1024**2],['吉字节','GB',1024**3],['太字节','TB',1024**4]] }, temperature: { name: '温度', units: [['摄氏度','°C','C'],['华氏度','°F','F'],['开尔文','K','K']] } };
const conversion = { category: 'length', from: 0, to: 1, value: '1' };
function convertedValue() { const category = units[conversion.category]; const value = Number(conversion.value); if (!Number.isFinite(value)) return NaN; const from = category.units[conversion.from]; const to = category.units[conversion.to]; if (conversion.category === 'temperature') { const celsius = from[2] === 'F' ? (value - 32) * 5 / 9 : from[2] === 'K' ? value - 273.15 : value; return to[2] === 'F' ? celsius * 9 / 5 + 32 : to[2] === 'K' ? celsius + 273.15 : celsius; } return value * from[2] / to[2]; }
const unitOptions = (category, selected) => category.units.map((unit, index) => `<option value="${index}" ${index === selected ? 'selected' : ''}>${unit[0]} (${unit[1]})</option>`).join('');
function convert() { const category = units[conversion.category]; return heading('单位转换', '覆盖长度、重量、面积、体积、速度、时间、数据和温度。', '<span class="saved-badge">高精度换算</span>') + `<div class="converter-card"><div class="field"><label for="conversionCategory">换算类型</label><select id="conversionCategory">${Object.entries(units).map(([key, item]) => `<option value="${key}" ${key === conversion.category ? 'selected' : ''}>${item.name}</option>`).join('')}</select></div><div class="conversion-row"><div class="field"><label for="fromUnit">从</label><select id="fromUnit">${unitOptions(category, conversion.from)}</select><input id="conversionValue" type="number" step="any" inputmode="decimal" value="${escapeHtml(conversion.value)}" aria-label="输入数值"></div><button class="swap" data-swap aria-label="交换单位">⇄</button><div class="field"><label for="toUnit">到</label><select id="toUnit">${unitOptions(category, conversion.to)}</select><div class="conversion-result" aria-live="polite"><small>结果</small><strong>${formatNumber(convertedValue())}</strong><span>${category.units[conversion.to][1]}</span></div></div></div><button class="secondary copy-button" data-copy-conversion>复制结果</button><span class="copy-status" id="copyStatus"></span></div>`; }

// Words ----------------------------------------------------------------------
function filteredWords() { const query = state.wordQuery.trim().toLowerCase(); return state.words.filter((word) => (!query || `${word.word} ${word.meaning} ${word.example}`.toLowerCase().includes(query)) && (state.wordFilter === 'all' || (state.wordFilter === 'mastered' ? word.mastered : !word.mastered))); }
function words() { const list = filteredWords(); const pageSize = 5; const pageCount = Math.max(1, Math.ceil(list.length / pageSize)); state.wordPage = Math.min(state.wordPage, pageCount); const pageItems = list.slice((state.wordPage - 1) * pageSize, state.wordPage * pageSize); const items = pageItems.length ? pageItems.map((word) => `<article class="word-item ${word.mastered ? 'mastered' : ''}"><div class="word-main"><strong>${escapeHtml(word.word)}</strong><span>${escapeHtml(word.meaning)}</span>${word.example ? `<small>${escapeHtml(word.example)}</small>` : ''}</div><span class="word-state">${word.mastered ? '已掌握' : '待复习'}</span><div class="word-actions"><button class="text-btn" data-toggle-word="${escapeHtml(word.id)}">${word.mastered ? '标为待复习' : '标记掌握'}</button><button class="icon-btn small" data-edit-word="${escapeHtml(word.id)}" aria-label="编辑 ${escapeHtml(word.word)}">✎</button><button class="icon-btn small" data-delete-word="${escapeHtml(word.id)}" aria-label="删除 ${escapeHtml(word.word)}">×</button></div></article>`).join('') : '<div class="empty compact">没有匹配的单词。试试添加一个新词。</div>'; const pages = Array.from({ length: pageCount }, (_, index) => `<button class="page-btn ${state.wordPage === index + 1 ? 'active' : ''}" data-word-page="${index + 1}">${index + 1}</button>`).join(''); const practice = state.words.filter((word) => !word.mastered); const practiceWord = practice.length ? practice[state.practiceIndex % practice.length] : null; const editing = state.editWordId ? state.words.find((word) => word.id === state.editWordId) : null; return heading('单词本', '添加、搜索、复习并标记掌握状态；数据只保存在当前设备。', '<span class="saved-badge">● 本机保存</span>') + `<div class="words-layout"><div><form id="wordForm" class="word-form"><div class="field"><label for="wordInput">单词</label><input id="wordInput" required maxlength="80" placeholder="例如：concise" value="${escapeHtml(editing?.word || '')}"></div><div class="field"><label for="meaningInput">释义</label><input id="meaningInput" required maxlength="160" placeholder="例如：简洁的" value="${escapeHtml(editing?.meaning || '')}"></div><div class="field"><label for="exampleInput">例句（可选）</label><input id="exampleInput" maxlength="200" placeholder="例如：Keep it concise." value="${escapeHtml(editing?.example || '')}"></div><div class="form-actions"><button class="primary" type="submit">${editing ? '保存修改' : '添加单词'}</button>${editing ? '<button class="secondary" type="button" data-cancel-edit>取消</button>' : ''}</div></form><div class="list-toolbar"><div class="search-box"><span aria-hidden="true">⌕</span><input id="wordSearch" value="${escapeHtml(state.wordQuery)}" placeholder="搜索单词、释义或例句" aria-label="搜索单词"></div><div class="filter-tabs">${[['all','全部'],['learning','待复习'],['mastered','已掌握']].map(([key, label]) => `<button class="filter-btn ${state.wordFilter === key ? 'active' : ''}" data-word-filter="${key}">${label}</button>`).join('')}</div></div><div class="word-list">${items}</div><div class="pagination"><span>${list.length ? `${(state.wordPage - 1) * pageSize + 1}–${Math.min(state.wordPage * pageSize, list.length)} / ${list.length}` : '0 个单词'}</span><div>${pages}</div></div></div><aside class="practice-panel"><div class="subhead"><div><p class="section-kicker">DAILY REVIEW</p><h3>快速复习</h3></div><span class="count-badge">${practice.length} 待复习</span></div>${practiceWord ? `<div class="practice-card"><small>看英文，回想中文释义</small><strong>${escapeHtml(practiceWord.word)}</strong>${state.practiceReveal ? `<p>${escapeHtml(practiceWord.meaning)}</p>${practiceWord.example ? `<small>${escapeHtml(practiceWord.example)}</small>` : ''}` : '<p class="practice-placeholder">点击查看答案</p>'}</div><div class="practice-actions"><button class="secondary" data-practice-reveal>${state.practiceReveal ? '隐藏答案' : '查看答案'}</button><button class="primary" data-practice-next>下一个</button></div>` : '<div class="empty compact">太棒了，所有单词都已掌握。</div>'}<hr><button class="secondary full-width" data-export-words>导出词汇 JSON</button><label class="secondary file-button">导入词汇 JSON<input id="importWords" type="file" accept="application/json"></label></aside></div>`; }
function saveWords() { saveStored(STORAGE.words, state.words); }

function render() { const renderers = { calculator, calendar, weather, convert, words }; workspace.innerHTML = (renderers[state.tool] || calculator)(); document.documentElement.dataset.theme = state.theme; if (state.tool === 'calendar') ensureHolidayYear(state.month.getFullYear()); }

// Delegated events keep the app small while allowing each tool to re-render.
nav.addEventListener('click', (event) => { const button = event.target.closest('[data-tool]'); if (button) selectTool(button.dataset.tool); });
workspace.addEventListener('click', async (event) => {
  const key = event.target.closest('[data-key]'); if (key) return calculatorKey(key.dataset.key);
  const history = event.target.closest('[data-history]'); if (history) { state.calcExpr = history.dataset.history; state.calcJustEvaluated = true; saveCalculator(); return render(); }
  if (event.target.closest('[data-clear-calc-history]')) { state.calcHistory = []; saveCalculator(); return render(); }
  const month = event.target.closest('[data-month]'); if (month) { state.month = new Date(state.month.getFullYear(), state.month.getMonth() + Number(month.dataset.month), 1); return render(); }
  if (event.target.closest('[data-today]')) { state.month = new Date(today.getFullYear(), today.getMonth(), 1); state.selectedDate = dateKey(today); return render(); }
  const day = event.target.closest('[data-date]'); if (day) { state.selectedDate = day.dataset.date; return render(); }
  const deleteEvent = event.target.closest('[data-delete-event]'); if (deleteEvent) { state.events[state.selectedDate] = (state.events[state.selectedDate] || []).filter((item) => item.id !== deleteEvent.dataset.deleteEvent); saveEvents(); return render(); }
  const locate = event.target.closest('[data-locate]'); if (locate) { if (!navigator.geolocation) return toast('当前浏览器不支持定位', 'error'); state.weatherLoading = true; render(); return navigator.geolocation.getCurrentPosition((position) => fetchWeather(position.coords.latitude, position.coords.longitude, '当前位置'), () => { state.weatherLoading = false; state.weatherError = '无法获取当前位置，请检查浏览器权限'; render(); }); }
  if (event.target.closest('[data-refresh-weather]') && state.weather) return fetchWeather(state.weather.latitude, state.weather.longitude, state.weather.name);
  if (event.target.closest('[data-swap]')) { [conversion.from, conversion.to] = [conversion.to, conversion.from]; return render(); }
  if (event.target.closest('[data-copy-conversion]')) { const value = `${formatNumber(convertedValue())} ${units[conversion.category].units[conversion.to][1]}`; try { await navigator.clipboard.writeText(value); $('#copyStatus').textContent = '已复制'; } catch { toast('浏览器不允许访问剪贴板，请手动复制', 'error'); } return; }
  const toggle = event.target.closest('[data-toggle-word]'); if (toggle) { const word = state.words.find((item) => item.id === toggle.dataset.toggleWord); if (word) word.mastered = !word.mastered; saveWords(); return render(); }
  const edit = event.target.closest('[data-edit-word]'); if (edit) { state.editWordId = edit.dataset.editWord; return render(); }
  const deleteWord = event.target.closest('[data-delete-word]'); if (deleteWord) { state.words = state.words.filter((item) => item.id !== deleteWord.dataset.deleteWord); saveWords(); return render(); }
  if (event.target.closest('[data-cancel-edit]')) { state.editWordId = null; return render(); }
  const filter = event.target.closest('[data-word-filter]'); if (filter) { state.wordFilter = filter.dataset.wordFilter; state.wordPage = 1; return render(); }
  const page = event.target.closest('[data-word-page]'); if (page) { state.wordPage = Number(page.dataset.wordPage); return render(); }
  if (event.target.closest('[data-practice-reveal]')) { state.practiceReveal = !state.practiceReveal; return render(); }
  if (event.target.closest('[data-practice-next]')) { state.practiceIndex++; state.practiceReveal = false; return render(); }
  if (event.target.closest('[data-export-words]')) { const blob = new Blob([JSON.stringify(state.words, null, 2)], { type: 'application/json' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `onebox-words-${dateKey(today)}.json`; link.click(); URL.revokeObjectURL(link.href); toast('词汇已导出'); }
});
workspace.addEventListener('input', (event) => { if (event.target.id === 'conversionValue') { conversion.value = event.target.value; const output = $('.conversion-result strong'); if (output) output.textContent = formatNumber(convertedValue()); } if (event.target.id === 'wordSearch') { state.wordQuery = event.target.value; state.wordPage = 1; render(); const input = $('#wordSearch'); if (input) { input.focus(); input.setSelectionRange(input.value.length, input.value.length); } } });
workspace.addEventListener('change', (event) => {
  if (event.target.id === 'conversionCategory') { conversion.category = event.target.value; conversion.from = 0; conversion.to = 1; return render(); }
  if (event.target.id === 'fromUnit') { conversion.from = Number(event.target.value); return render(); }
  if (event.target.id === 'toUnit') { conversion.to = Number(event.target.value); return render(); }
  if (event.target.id === 'importWords' && event.target.files?.[0]) { const reader = new FileReader(); reader.onload = () => { try { const imported = JSON.parse(reader.result); if (!Array.isArray(imported)) throw Error(); const valid = imported.filter((item) => item?.word && item?.meaning).map((item) => ({ id: uid(), word: String(item.word).trim(), meaning: String(item.meaning).trim(), example: String(item.example || ''), mastered: Boolean(item.mastered), createdAt: Date.now() })); state.words = [...valid, ...state.words]; saveWords(); render(); toast(`已导入 ${valid.length} 个单词`); } catch { toast('导入失败：文件不是有效的词汇 JSON', 'error'); } }; reader.readAsText(event.target.files[0]); }
});
workspace.addEventListener('submit', (event) => { event.preventDefault(); if (event.target.id === 'eventForm') { const title = $('#eventTitle').value.trim(); if (!title) return; const key = $('#eventDate').value; state.events[key] ||= []; state.events[key].push({ id: uid(), title, time: $('#eventTime').value, note: $('#eventNote').value.trim() }); saveEvents(); render(); toast('日程已添加'); } if (event.target.id === 'weatherSearch') searchWeather($('#cityInput').value); if (event.target.id === 'wordForm') { const word = $('#wordInput').value.trim(); const meaning = $('#meaningInput').value.trim(); const example = $('#exampleInput').value.trim(); if (state.editWordId) { const existing = state.words.find((item) => item.id === state.editWordId); if (existing) Object.assign(existing, { word, meaning, example }); state.editWordId = null; toast('单词已更新'); } else { state.words.unshift({ id: uid(), word, meaning, example, mastered: false, createdAt: Date.now() }); toast('单词已添加'); } saveWords(); render(); } });
document.addEventListener('keydown', (event) => { if (state.tool !== 'calculator' || event.target.matches('input, textarea, select')) return; const keyMap = { Enter: '=', Escape: 'AC', Backspace: '⌫', '*': '×', '/': '÷', '-': '−' }; const key = keyMap[event.key] || event.key; if (/^[0-9.+()%,]$/.test(key) || ['=', 'AC', '⌫', '×', '÷', '−'].includes(key)) { event.preventDefault(); calculatorKey(key === ',' ? '.' : key); } });

$('#themeBtn').addEventListener('click', () => { state.theme = state.theme === 'dark' ? 'light' : 'dark'; localStorage.setItem(STORAGE.theme, state.theme); document.documentElement.dataset.theme = state.theme; $('#themeBtn').textContent = state.theme === 'dark' ? '☀' : '◐'; $('#themeBtn').setAttribute('aria-label', state.theme === 'dark' ? '切换到浅色模式' : '切换到深色模式'); });
let installPrompt; window.addEventListener('beforeinstallprompt', (event) => { event.preventDefault(); installPrompt = event; $('#installBtn').hidden = false; }); $('#installBtn').addEventListener('click', async () => { if (!installPrompt) return; installPrompt.prompt(); await installPrompt.userChoice; installPrompt = null; $('#installBtn').hidden = true; });
window.addEventListener('online', () => { $('#connectionStatus').textContent = '在线'; toast('网络已恢复'); }); window.addEventListener('offline', () => { $('#connectionStatus').textContent = '离线'; toast('已切换到离线模式'); }); window.addEventListener('hashchange', () => selectTool(location.hash.slice(1)));
const now = new Date(); $('#heroDay').textContent = now.getDate(); $('#heroMonth').textContent = now.toLocaleDateString('en-US', { month: 'short', year: 'numeric' }).toUpperCase(); $('#themeBtn').textContent = state.theme === 'dark' ? '☀' : '◐'; $('#themeBtn').setAttribute('aria-label', state.theme === 'dark' ? '切换到浅色模式' : '切换到深色模式'); $('#connectionStatus').textContent = navigator.onLine ? '在线' : '离线'; renderNav(); render(); if ('serviceWorker' in navigator) navigator.serviceWorker.register('sw.js').catch(() => {});
